#!/bin/sh
# Generated by scripts/build-launchers.mjs; edit this template, not dist/bin/.
set -eu

TARGET="__TARGET__"
MIN_NODE_VERSION="__MIN_NODE_VERSION__"

# Package managers expose bins through symlinks, sometimes relative chains.
SOURCE="$0"
while [ -L "$SOURCE" ]; do
  DIR="$(cd -P "$(dirname "$SOURCE")" && pwd)"
  SOURCE="$(readlink "$SOURCE")"
  case "$SOURCE" in
    /*) ;;
    *) SOURCE="$DIR/$SOURCE" ;;
  esac
done
SCRIPT_DIR="$(cd -P "$(dirname "$SOURCE")" && pwd)"
ENTRY="$SCRIPT_DIR/$TARGET"

# Safe identity probe: service preflight verifies bytes before invoking this.
if [ "${1-}" = "--print-launcher" ]; then
  printf '%s\n' "$SCRIPT_DIR"
  exit 0
fi

case "${PI_WEB_RUNTIME:-auto}" in
  auto|node|bun) ;;
  *) printf 'pi-web: invalid PI_WEB_RUNTIME=%s; use node, bun or auto.\n' "$PI_WEB_RUNTIME" >&2; exit 2 ;;
esac

usable_runtime() {
  [ -x "$2" ] || return 1
  if [ "$1" = bun ]; then
    # Detect the actual engine, not the executable name. PTY support is separate.
    "$2" -e 'process.exit(process.versions.bun ? 0 : 1)' >/dev/null 2>&1
  else
    "$2" -e 'if(process.versions.bun || !process.versions.node)process.exit(1);const base=(v)=>v.split("-")[0].split(".").map(Number);const current=base(process.versions.node),minimum=base("'$MIN_NODE_VERSION'");for(let i=0;i<minimum.length;i++){if(current[i]>minimum[i])break;if(current[i]<minimum[i])process.exit(1);}' >/dev/null 2>&1
  fi
}

# A subshell scopes discovery variables without non-POSIX local declarations.
find_runtime() (
  kind="$1"
  shift
  found="$(command -v "$kind" 2>/dev/null || true)"
  for candidate in "$found" "$@"; do
    if usable_runtime "$kind" "$candidate"; then
      printf '%s\n' "$candidate"
      exit 0
    fi
  done
  exit 1
)

RUNTIME_KIND=""
RUNTIME_EXECUTABLE=""
preference="${PI_WEB_RUNTIME:-auto}"
if [ "$preference" != bun ] && RUNTIME_EXECUTABLE="$(find_runtime node __NODE_CANDIDATES__)"; then
  RUNTIME_KIND=node
elif [ "$preference" != node ] && RUNTIME_EXECUTABLE="$(find_runtime bun __BUN_CANDIDATES__)"; then
  RUNTIME_KIND=bun
else
  printf 'pi-web: no usable runtime for PI_WEB_RUNTIME=%s; install node >= %s or Bun, or select node|bun|auto.\n' "$preference" "$MIN_NODE_VERSION" >&2
  exit 127
fi

if [ ! -f "$ENTRY" ] || [ ! -r "$ENTRY" ]; then
  printf 'pi-web: entrypoint is missing or unreadable: %s\n' "$ENTRY" >&2
  exit 127
fi

# Use exactly the startup selection and entrypoint checks without starting JS.
if [ "${1-}" = "--print-runtime" ]; then
  printf '%s\n' "$RUNTIME_KIND"
  exit 0
fi
# Service prerequisites run on the same interpreter as startup. Only sessiond
# owns the required terminal capability; the web/API and CLI do not need a PTY.
if [ "${1-}" = "--check-runtime" ]; then
  PREFLIGHT="$SCRIPT_DIR/../runtimePreflight.js"
  if [ ! -f "$PREFLIGHT" ] || [ ! -r "$PREFLIGHT" ]; then
    printf 'pi-web: runtime preflight entrypoint is missing or unreadable: %s\n' "$PREFLIGHT" >&2
    exit 127
  fi
  if [ "$TARGET" = "../server/sessiond.js" ]; then
    exec "$RUNTIME_EXECUTABLE" "$PREFLIGHT" --terminal
  fi
  exec "$RUNTIME_EXECUTABLE" "$PREFLIGHT"
fi
exec "$RUNTIME_EXECUTABLE" "$ENTRY" "$@"
